using WypozyczalniaSportowa.Domain.Pricing;
namespace WypozyczalniaSportowa.Domain; public sealed class Tent : SportEquipment { private int _capacity; public Tent(string n, decimal r, int capacity) : base(n, r) => Capacity = capacity; internal Tent(int id, string n, decimal r, bool a, bool s, int c) : base(id, n, r, a, s) => Capacity = c; public int Capacity { get => _capacity; private set => _capacity = value is < 1 or > 12 ? throw new Exceptions.DomainValidationException("Namiot: pojemność 1-12 osób.") : value; } public override string Kind => "Namiot"; public override int Detail => Capacity; public override decimal CalculateRentalPrice(RentalPeriod p, IPricingStrategy s) => s.Calculate(DailyRate, p) * Math.Max(1, Capacity / 2); public override Equipment CloneEntity(bool deep) => new Tent(Id, Name, DailyRate, IsAvailable, NeedsService, Capacity); public override string ToString() => $"{base.ToString()}, osób: {Capacity}"; }
